        <div class="local-note"><span class="status-dot"></span><span id="save-state" class="save-state" role="status">离线可用 · 自动保存草稿</span><button id="help" class="text-button usage-help-button" title="使用方法（F1）">${t(`help`,17)}<span>使用方法</span></button></div>
